cards.extra_styles:
.hero {
  display: grid;
  grid-template-columns: minmax(360px,1.8fr) repeat(4,minmax(120px,.55fr));
  width: 100%;
}
.hero > div {
  min-width: 0;
  padding: 17px;
  border-right: 1px solid rgba(255,255,255,.07);
}
.hero > div:last-child {
  border-right: none;
}
.hero-brand {
  display: flex;
  align-items: center;
  gap: 14px;
}
.hero-logo {
  width: 58px;
  height: 58px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(132,70,255,.25), rgba(4,9,16,.98) 70%);
  border: 1px solid rgba(140,78,255,.42);
}
.hero-logo ha-icon {
  width: 38px;
  color: #9a62ff;
}
.hero-brand b {
  display: block;
  color: #f5f7fb;
  font-size: 21px;
}
.hero-brand span,
.hero-stat span {
  display: block;
  margin-top: 5px;
  color: rgba(255,255,255,.48);
  font-size: 9px;
}
.hero-stat {
  display: flex;
  flex-direction: column;
  justify-content: center;
}
.hero-stat b {
  display: block;
  margin-top: 6px;
  color: rgba(255,255,255,.92);
  font-size: 14px;
}
@media(max-width:1000px) {
  .hero {
    grid-template-columns: 1fr 1fr;
  }
  .hero-brand {
    grid-column: 1 / -1;
  }
}

.panel { padding: 17px; }
.section-title {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 10px;
}
.section-title > span {
  color: #5aa7ff;
  font-size: 14px;
  font-weight: 800;
}
.section-title b {
  padding: 5px 9px;
  border-radius: 6px;
  font-size: 9px;
}
.section-title .ok {
  color: #39d46b;
  background: rgba(57,212,107,.12);
  border: 1px solid rgba(57,212,107,.28);
}
.section-title .warn {
  color: #ffb63e;
  background: rgba(255,182,62,.12);
  border: 1px solid rgba(255,182,62,.34);
}
.ingest-disc {
  display: grid;
  grid-template-columns: 76px minmax(0,1fr);
  align-items: center;
  gap: 13px;
  margin-top: 18px;
}
.disc-icon {
  width: 70px;
  height: 70px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(91,166,255,.3), rgba(5,11,18,.98) 70%);
  border: 1px solid rgba(91,166,255,.4);
}
.disc-icon ha-icon {
  width: 46px;
  color: #dbe8f7;
}
.ingest-disc b {
  display: block;
  color: rgba(255,255,255,.94);
  font-size: 19px;
}
.ingest-disc span {
  display: block;
  margin-top: 6px;
  color: rgba(255,255,255,.53);
  font-size: 11px;
}
.progress-head {
  display: flex;
  justify-content: space-between;
  margin-top: 20px;
}
.progress-head span {
  color: rgba(255,255,255,.62);
  font-size: 10px;
}
.progress-head b {
  color: #ffb63e;
  font-size: 24px;
}
.bar {
  height: 9px;
  margin-top: 8px;
  overflow: hidden;
  border-radius: 10px;
  background: rgba(255,255,255,.07);
}
.bar div {
  height: 100%;
  background: linear-gradient(90deg,#278cff,#5aa7ff);
}
.stage-row {
  display: grid;
  grid-template-columns: repeat(5,1fr);
  gap: 5px;
  margin-top: 20px;
}
.stage-row > div {
  text-align: center;
  color: rgba(255,255,255,.35);
}
.stage-row span {
  display: block;
  font-size: 19px;
}
.stage-row b {
  display: block;
  margin-top: 4px;
  font-size: 7px;
  text-transform: capitalize;
}
.stage-row .done { color: #39d46b; }
.stage-row .active { color: #ffb63e; }

